/* 棱镜 Prism — 多维数据探索台 · 深色高密度主题 */
:root {
  --bg: #0d1117; --panel: #141a23; --panel2: #19212e; --panel3: #1f2938;
  --line: #242f3f; --line2: #2f3d52;
  --tx: #dbe4f0; --mut: #8b99ad; --faint: #5d6b80;
  --acc: #5aa2f0; --warn: #ff9f5a;
  --anchor: #ffd166;
}
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--tx);
  font: 13px/1.55 "Segoe UI", system-ui, "Microsoft YaHei", "PingFang SC", sans-serif;
  display: flex; flex-direction: column; overflow: hidden;
}
button {
  font: inherit; color: var(--tx); background: var(--panel2);
  border: 1px solid var(--line2); border-radius: 6px; padding: 4px 10px; cursor: pointer;
}
button:hover:not(:disabled) { border-color: var(--acc); color: #fff; }
button:disabled { opacity: .38; cursor: default; }
input, select {
  font: inherit; color: var(--tx); background: #0f141d;
  border: 1px solid var(--line2); border-radius: 6px; padding: 3px 8px;
}
input:focus, select:focus { outline: none; border-color: var(--acc); }
kbd { font: 10px/1 Consolas, monospace; color: var(--faint); }

/* ---------- 顶栏：状态账本 ---------- */
#topbar {
  display: flex; align-items: center; gap: 16px; padding: 8px 14px;
  background: linear-gradient(180deg, #151d29, #111823);
  border-bottom: 1px solid var(--line); flex: none; flex-wrap: wrap;
}
.brand { display: flex; gap: 10px; align-items: center; }
.logo {
  width: 32px; height: 32px; border-radius: 8px;
  background: linear-gradient(135deg, #5aa2f0, #8f7bf2);
  display: grid; place-items: center; font-size: 17px; color: #fff; flex: none;
}
.brand h1 { margin: 0; font-size: 15px; letter-spacing: .5px; }
.brand h1 em { font-style: normal; color: var(--mut); font-weight: 400; font-size: 12px; }
#data-meta { margin: 0; font-size: 11px; color: var(--mut); font-variant-numeric: tabular-nums; }
#ledger { flex: 1; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; min-width: 240px; }
.ledger-empty { color: var(--faint); font-size: 12px; }
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--panel2); border: 1px solid var(--line2); border-radius: 999px;
  padding: 2px 4px 2px 9px; font-size: 12px; font-variant-numeric: tabular-nums; white-space: nowrap;
}
.chip .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--c, #888); flex: none; }
.chip b { font-weight: 600; }
.chip .cnt { color: var(--mut); font-size: 11px; }
.chip.warn { border-color: #a5582a; background: #2a1d12; }
.chip.warn .cnt { color: var(--warn); }
.chip .x {
  width: 18px; height: 18px; border-radius: 50%; border: none; background: transparent;
  color: var(--mut); padding: 0; line-height: 1; font-size: 12px; cursor: pointer;
}
.chip .x:hover { background: #33415a; color: #fff; }
.chip.proj { border-style: dashed; cursor: default; }
.top-actions { display: flex; gap: 6px; align-items: center; }

/* ---------- 三栏布局 ---------- */
#layout { flex: 1; display: grid; grid-template-columns: 258px minmax(0, 1fr) 348px; min-height: 0; }
#rail { border-right: 1px solid var(--line); overflow-y: auto; background: var(--panel); display: flex; flex-direction: column; min-height: 0; }
#dims { flex: 1; min-height: 0; }
#side { border-left: 1px solid var(--line); background: var(--panel); display: flex; flex-direction: column; min-height: 0; }
.rail-h {
  padding: 10px 12px 6px; font-size: 11px; letter-spacing: 1px; color: var(--mut);
  display: flex; justify-content: space-between; align-items: baseline; flex: none;
}
.rail-h:not(:first-child) { border-top: 1px solid var(--line); }
.rail-h .hint { font-size: 10px; color: var(--faint); letter-spacing: 0; }

/* ---------- 维度目录 ---------- */
.dim { border-bottom: 1px solid var(--line); }
.dim-head { display: flex; align-items: center; gap: 7px; padding: 6px 10px; cursor: pointer; }
.dim-head:hover { background: var(--panel2); }
.dim.on { background: #1c2432; box-shadow: inset 2px 0 0 var(--c); }
.dim-head .dot { width: 9px; height: 9px; border-radius: 3px; background: var(--c); flex: none; }
.dim-head .nm { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tag { font-size: 10px; color: var(--faint); border: 1px solid var(--line); border-radius: 4px; padding: 0 4px; flex: none; }
.tag.proj { color: var(--acc); border-color: #31537d; }
.fcnt { color: var(--c); font-size: 10px; flex: none; }
.fbtn { font-size: 11px; padding: 1px 7px; border-radius: 5px; flex: none; }
.dim-panel { padding: 4px 12px 10px; background: #10151e; }
.vrow { display: flex; align-items: center; gap: 7px; padding: 2px 4px; border-radius: 4px; cursor: pointer; font-size: 12px; }
.vrow:hover { background: var(--panel2); }
.vrow input { accent-color: var(--c); margin: 0; }
.vrow .vn { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.vrow .vc { color: var(--mut); font-size: 11px; font-variant-numeric: tabular-nums; }
.range-row { display: flex; gap: 6px; align-items: center; margin: 6px 0; }
.range-row input { width: 84px; font-variant-numeric: tabular-nums; }
.range-row input[name-q] { flex: 1; }
.panel-actions { display: flex; gap: 6px; margin-top: 4px; }
.panel-actions button { font-size: 11px; padding: 2px 8px; }
.dim-panel input[data-nameq] { width: 100%; }

/* ---------- 操作历史 ---------- */
