177	  /* ---------------- 分组构建 ---------------- */
178	  function buildGroups(dim, kept) {
179	    const keptSet = new Set(kept.map(r => r.id));
180	    const sel = selection ? IDX.get(selection) : null;
181	    const groups = [];
182	
183	    if (dim.type === 'num') {
184	      const smin = dim.stats.min, w = ((dim.stats.max - smin) / NUM_BINS) || 1;
185	      for (let i = 0; i < NUM_BINS; i++) {
186	        groups.push({
187	          label: fmtNum(Math.round(smin + i * w)) + '–' + fmtNum(Math.round(smin + (i + 1) * w)),
188	          lo: smin + i * w, hi: smin + (i + 1) * w, total: 0, kept: 0,
189	        });
190	      }
191	      const bin = x => Math.min(NUM_BINS - 1, Math.max(0, Math.floor((x - smin) / w)));
192	      for (const r of RECORDS) { const g = groups[bin(r[dim.id])]; g.total++; if (keptSet.has(r.id)) g.kept++; }
193	      groups.anchor = sel ? bin(sel[dim.id]) : -1;
194	    } else if (dim.type === 'highcat') {
195	      const m = new Map();
196	      for (const r of RECORDS) {
197	        let g = m.get(r.id);
198	        if (!g) { g = { label: r.name, value: r.id, total: 0, kept: 0 }; m.set(r.id, g); }
199	        g.total++; if (keptSet.has(r.id)) g.kept++;
200	      }
201	      let all = [...m.values()].sort((a, b) => b.total - a.total);
202	      if (!topExpanded && all.length > HIGH_TOPK) {
203	        const hid = all.length - HIGH_TOPK;
204	        all = all.slice(0, HIGH_TOPK);
205	        all.hidden = hid; // slice 会丢弃自定义属性，需在切片后重挂
206	      }
207	      all.anchor = sel ? all.findIndex(g => g.value === sel.id) : -1;
208	      return all; // 注：anchor/hidden 挂在返回数组上
209	    } else {
210	      const byVal = new Map();
211	      for (const v of dim.values) { const g = { label: v, value: v, total: 0, kept: 0 }; byVal.set(v, g); groups.push(g); }
212	      for (const r of RECORDS) {
213	        const g = byVal.get(String(r[dim.id]));
214	        if (g) { g.total++; if (keptSet.has(r.id)) g.kept++; }
215	      }
216	      if (dim.type === 'cat') groups.sort((a, b) => b.total - a.total);
217	      groups.anchor = sel ? groups.findIndex(g => g.label === String(sel[dim.id])) : -1;
218	    }
219	    return groups;
220	  }
