360	  function chartSVG(dim, groups) {
361	    const wrap = $('chart-wrap');
362	    const W = Math.max(360, wrap.clientWidth - 4), H = 340;
363	    const padL = 48, padR = 10, padT = 18, padB = 48;
364	    const iw = W - padL - padR, ih = H - padT - padB;
365	    const max = Math.max(1, ...groups.map(g => g.total));
366	    const n = groups.length;
367	    const slot = iw / n;
368	    const bw = Math.max(2, slot - (n > 60 ? 0.5 : Math.min(10, slot * 0.25)));
369	    const f = st().filters[dim.id];
370	    const activeSet = f && f.t === 'cat' ? f.v : null;
371	
372	    let s = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '">';
373	    for (let i = 0; i <= 4; i++) {
374	      const v = max * i / 4, y = padT + ih - (v / max) * ih;
375	      s += '<line x1="' + padL + '" y1="' + y + '" x2="' + (W - padR) + '" y2="' + y + '" stroke="#22303f"/>' +
376	        '<text x="' + (padL - 6) + '" y="' + (y + 3) + '" text-anchor="end" font-size="10" fill="#71809a">' + fmtNum(Math.round(v)) + '</text>';
377	    }
378	    const labEvery = n <= 26 ? 1 : Math.ceil(n / 26);
379	    chartMeta = groups;
380	    for (let i = 0; i < n; i++) {
381	      const g = groups[i];
382	      const x = padL + i * slot + (slot - bw) / 2;
383	      const ht = Math.max(0.5, (g.total / max) * ih);
384	      const hk = Math.max(0.5, (g.kept / max) * ih);
385	      const isActive = activeSet ? activeSet.indexOf(g.label) >= 0 : false;
386	      const isAnchor = i === groups.anchor;
387	      s += '<rect data-i="' + i + '" x="' + x + '" y="' + (padT + ih - ht) + '" width="' + bw + '" height="' + ht +
388	        '" rx="2" fill="' + rgba(dim.color, 0.16) + '"/>';
389	      s += '<rect class="bar" data-i="' + i + '" x="' + x + '" y="' + (padT + ih - hk) + '" width="' + bw + '" height="' + hk +
390	        '" rx="2" fill="' + rgba(dim.color, isActive ? 1 : 0.72) + '"' +
391	        (isActive ? ' stroke="#fff" stroke-width="1"' : '') + '/>';
392	      if (isAnchor) {
393	        const yy = padT + ih - ht - 8;
394	        s += '<circle cx="' + (x + bw / 2) + '" cy="' + yy + '" r="7" fill="#ffd166" stroke="#5a4a10"/>' +
395	          '<text x="' + (x + bw / 2) + '" y="' + (yy + 3.5) + '" text-anchor="middle" font-size="9" font-weight="700" fill="#3a2c00">锚</text>';
396	      }
397	      if (i % labEvery === 0) {
398	        const lbl = g.label.length > 7 ? g.label.slice(0, 6) + '…' : g.label;
399	        const col = isActive ? '#fff' : '#8b99ad';
400	        if (n > 14) {
401	          s += '<text transform="translate(' + (x + bw / 2 + 4) + ',' + (padT + ih + 14) + ') rotate(-38)" text-anchor="end" font-size="10" fill="' + col + '">' + esc(lbl) + '</text>';
402	        } else {
403	          s += '<text x="' + (x + bw / 2) + '" y="' + (padT + ih + 16) + '" text-anchor="middle" font-size="10.5" fill="' + col + '">' + esc(lbl) + '</text>';
404	        }
405	      }
406	    }
407	    s += '<line x1="' + padL + '" y1="' + (padT + ih) + '" x2="' + (W - padR) + '" y2="' + (padT + ih) + '" stroke="#33415a"/></svg>';
408	    return s;
409	  }
