488	  /* ---------------- 工具 ---------------- */
489	  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
490	  function rgba(hex, a) {
491	    const n = parseInt(hex.slice(1), 16);
492	    return 'rgba(' + (n >> 16 & 255) + ',' + (n >> 8 & 255) + ',' + (n & 255) + ',' + a + ')';
493	  }
494	  function fmtNum(v) { return v >= 10000 ? v.toLocaleString('en-US') : String(Math.round(v)); }
495	  function fmtWan(v) { return v >= 10000 ? (v / 10000).toFixed(1) + '亿' : v + '万'; }
496	  function fmtGdp(v) { return v >= 1000 ? (v / 1000).toFixed(1) + 'k' : String(v); }
497	  function fmtVal(d, v) {
