576	          Math.abs((f.lo == null ? -Infinity : f.lo) - (g.lo === -Infinity ? -Infinity : rlo)) < 1e-9 &&
577	          Math.abs((f.hi == null ? Infinity : f.hi) - (g.hi === Infinity ? Infinity : rhi)) < 1e-9;
578	        if (same) clearDim(dim.id);
