1	/* 棱镜 Prism — 多维数据探索台 · 深色高密度主题 */
2	:root {
3	  --bg: #0d1117; --panel: #141a23; --panel2: #19212e; --panel3: #1f2938;
4	  --line: #242f3f; --line2: #2f3d52;
5	  --tx: #dbe4f0; --mut: #8b99ad; --faint: #5d6b80;
6	  --acc: #5aa2f0; --warn: #ff9f5a;
7	  --anchor: #ffd166;
8	}
9	* { box-sizing: border-box; }
10	html, body { height: 100%; }
11	body {
12	  margin: 0; background: var(--bg); color: var(--tx);
13	  font: 13px/1.55 "Segoe UI", system-ui, "Microsoft YaHei", "PingFang SC", sans-serif;
14	  display: flex; flex-direction: column; overflow: hidden;
15	}
16	button {
17	  font: inherit; color: var(--tx); background: var(--panel2);
18	  border: 1px solid var(--line2); border-radius: 6px; padding: 4px 10px; cursor: pointer;
19	}
20	button:hover:not(:disabled) { border-color: var(--acc); color: #fff; }
21	button:disabled { opacity: .38; cursor: default; }
22	input, select {
23	  font: inherit; color: var(--tx); background: #0f141d;
24	  border: 1px solid var(--line2); border-radius: 6px; padding: 3px 8px;
25	}
26	input:focus, select:focus { outline: none; border-color: var(--acc); }
27	kbd { font: 10px/1 Consolas, monospace; color: var(--faint); }
28	
29	/* ---------- 顶栏：状态账本 ---------- */
30	#topbar {
31	  display: flex; align-items: center; gap: 16px; padding: 8px 14px;
32	  background: linear-gradient(180deg, #151d29, #111823);
33	  border-bottom: 1px solid var(--line); flex: none; flex-wrap: wrap;
34	}
35	.brand { display: flex; gap: 10px; align-items: center; }
36	.logo {
37	  width: 32px; height: 32px; border-radius: 8px;
38	  background: linear-gradient(135deg, #5aa2f0, #8f7bf2);
39	  display: grid; place-items: center; font-size: 17px; color: #fff; flex: none;
40	}
