47	  display: inline-flex; align-items: center; gap: 6px;
48	  background: var(--panel2); border: 1px solid var(--line2); border-radius: 999px;
49	  padding: 2px 4px 2px 9px; font-size: 12px; font-variant-numeric: tabular-nums; white-space: nowrap;
50	}
51	.chip .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--c, #888); flex: none; }
52	.chip b { font-weight: 600; }
53	.chip .cnt { color: var(--mut); font-size: 11px; }
54	.chip.warn { border-color: #a5582a; background: #2a1d12; }
55	.chip.warn .cnt { color: var(--warn); }
56	.chip .x {
57	  width: 18px; height: 18px; border-radius: 50%; border: none; background: transparent;
58	  color: var(--mut); padding: 0; line-height: 1; font-size: 12px; cursor: pointer;
